import{_ as t,o as r,c as e,ag as s}from"./chunks/framework.D5hoimZQ.js";const m=JSON.parse('{"title":"科学日报 · 2026-10-13（AI 系统架构）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/science-daily-2026-10-13.md","filePath":"topics/ai-system-architecture/science-daily-2026-10-13.md"}'),n={name:"topics/ai-system-architecture/science-daily-2026-10-13.md"};function i(a,o,c,g,l,d){return r(),e("div",null,[...o[0]||(o[0]=[s('<h1 id="科学日报-·-2026-10-13-ai-系统架构" tabindex="-1">科学日报 · 2026-10-13（AI 系统架构） <a class="header-anchor" href="#科学日报-·-2026-10-13-ai-系统架构" aria-label="Permalink to &quot;科学日报 · 2026-10-13（AI 系统架构）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-13.md</code> — 第36期 ｜ AI 板块（arXiv，10-09 批次）</p></blockquote><hr><h2 id="语言模型能玩-维基百科游戏-吗-导航追平人类但无超越-arxiv-2610-13948" tabindex="-1">语言模型能玩&quot;维基百科游戏&quot;吗？导航追平人类但无超越（arXiv:2610.13948） <a class="header-anchor" href="#语言模型能玩-维基百科游戏-吗-导航追平人类但无超越-arxiv-2610-13948" aria-label="Permalink to &quot;语言模型能玩&quot;维基百科游戏&quot;吗？导航追平人类但无超越（arXiv:2610.13948）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-13.md</code> ｜ arXiv: 2610.13948</p></blockquote><ul><li>任务：<strong>维基百科游戏</strong>——只能通过条目之间的<strong>链接</strong>抵达目标条目，作为<strong>超大文档集合信息检索导航</strong>的代理任务（需要专门语言/科学知识时更难）。</li><li>数据/方法：用 <strong>OpenAlex</strong> 构建<strong>超大规模的维基条目图 + 论文引用图</strong>（<strong>不依赖第三方 API</strong>，并开源构建/导航代码）。</li><li>对比：在 <strong>5 种维基语言 + 5 个学术文献数据集</strong>上，比较<strong>句向量模型 vs LLM</strong>，并以<strong>人类 + TF-IDF</strong> 为基线。</li><li>结果：<strong>没有任何模型显著胜过人类</strong>；最优模型（<strong>GPT-o3 mini、GPT-4o、QwQ:32B、DeepSeek-R1:70B</strong>）达到<strong>与人类相当</strong>的成功率；性能与排名<strong>随语言/主题明显变化</strong>。</li><li>洞察（对本库 <code>ai-system-architecture</code>）：<strong>&quot;能检索&quot;不等于&quot;比人更会找&quot;</strong>——在需要<strong>多跳导航</strong>的检索上模型只是<strong>追平人类</strong>，且<strong>跨语言/跨域不稳定</strong>。给实践者的警示：<strong>别默认&quot;最强 LLM 的检索一定更优&quot;。</strong></li></ul><hr><h2 id="ai-模型可以被-可证明地-藏起任意能力-arxiv-2610-13928" tabindex="-1">AI 模型可以被&quot;可证明地&quot;藏起任意能力（arXiv:2610.13928） <a class="header-anchor" href="#ai-模型可以被-可证明地-藏起任意能力-arxiv-2610-13928" aria-label="Permalink to &quot;AI 模型可以被&quot;可证明地&quot;藏起任意能力（arXiv:2610.13928）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-13.md</code> ｜ arXiv: 2610.13928</p></blockquote><ul><li>被攻破的前提：能力评估假设&quot;<strong>隐藏能力终究能被诱发</strong>&quot;。</li><li>攻击：用<strong>数字储物柜（digital lockers）<strong>把</strong>加密的神经网络嵌入宿主模型权重</strong>，只在收到<strong>秘密触发器</strong>时解密并执行。</li><li>保证：在<strong>密码学假设</strong>下，即使<strong>完全掌握权重</strong>，这些隐藏电路<strong>可被证明地难以诱发与解释</strong>——把此前&quot;<strong>藏固定字符串</strong>&quot;扩展到&quot;<strong>藏任意计算</strong>&quot;。</li><li>实验：PyTorch 概念验证；以<strong>小型化学反应预测</strong>（<strong>CBRN 相关能力的代理任务</strong>）评估<strong>微调、权重加噪、梯度式触发搜索、潜在对抗训练</strong>等诱发手段 → <strong>均被抵抗</strong>。</li><li>洞察（对本库 <code>ai-system-architecture</code> / <code>cybersecurity</code>）：<strong>&quot;诱发式能力审计&quot;存在原理上限</strong>——不是&quot;我们还没找到诱发方法&quot;，而是<strong>在密码学意义上可以被证明挖不出来</strong>。与 Echo Gap / 守卫模型系列同构：<strong>凡以&quot;能被观测&quot;为依据的安全断言，都要先问观测通道能否被对抗地封死。</strong></li></ul><hr><h2 id="用自然语言直接设计蛋白质结构-prompteina-arxiv-2610-13917" tabindex="-1">用自然语言直接设计蛋白质结构：Prompteina（arXiv:2610.13917） <a class="header-anchor" href="#用自然语言直接设计蛋白质结构-prompteina-arxiv-2610-13917" aria-label="Permalink to &quot;用自然语言直接设计蛋白质结构：Prompteina（arXiv:2610.13917）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-13.md</code> ｜ arXiv: 2610.13917</p></blockquote><ul><li>问题：从头蛋白设计模型通常<strong>每种属性都要专门的输入表示</strong>，限制了能支持的设计目标。</li><li>方法：<strong>Prompteina</strong>——首个支持<strong>用自然语言</strong>指定更广设计目标的<strong>全原子结构生成模型</strong>（类比&quot;<strong>文生图</strong>&quot;）。</li><li>数据：<strong>Prompteina-Data</strong> = <strong>180 万结构 + 5000 万+ 配文</strong>（描述全局与残基级结构/功能属性）；经<strong>文本条件预训练 + 残基—文本对齐微调</strong>改造 <strong>Proteina-Complexa</strong>。</li><li>结果：<strong>18 项结构属性中 15 项</strong>优于基线；生成蛋白<strong>更贴近功能描述</strong>；结合蛋白设计中<strong>至少 20 个靶点里的 13 个</strong>领先，<strong>界面置信度 +14%</strong>。</li><li>实验验证：针对<strong>无已知从头结合体</strong>的靶点 <strong>GM2A</strong>，找到 <strong>9 个结合体</strong>，最强<strong>表观 K_D = 107 nM</strong>。</li><li>洞察（对本库 <code>ai-system-architecture</code> / <code>biomedicine</code>）：<strong>&quot;自然语言成为蛋白设计的一等接口&quot;</strong>——把设计目标从<strong>手工特征</strong>换成<strong>可描述的语言</strong>，是&quot;生成模型 + 通用条件接口&quot;（文生图→<strong>文生结构</strong>）范式的迁移。<strong>通用接口 &gt; 专用接口</strong>：可支持的目标集合不再被预先枚举。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/ai-system-architecture/index.md</code> ｜ 第36期 AI 板块</p></blockquote><p>关键词：维基百科游戏、Wikipedia Game、多跳导航、检索、OpenAlex、句向量、GPT-o3 mini、GPT-4o、QwQ:32B、DeepSeek-R1:70B、TF-IDF 基线；数字储物柜、digital lockers、加密神经网络、秘密触发器、可证明隐藏、能力审计上限、CBRN 代理任务、微调/权重加噪/梯度触发搜索/潜在对抗训练；Prompteina、Prompteina-Data、文生结构、全原子生成、Proteina-Complexa、残基—文本对齐、GM2A、K_D 107 nM、结合蛋白设计 关联：<code>topics/ai-system-architecture/science-daily-2026-10-12.md</code>（对齐泛化/激活表示、小世界指数）、<code>topics/ai-system-architecture/echo-gap-memory-reward-inflation.md</code>（解释≠忠实、自评分误差）、<code>topics/ai-system-architecture/dream-rsi.md</code>（递归自进化，另见同日 <code>intelligence-self-learning</code>）、<code>topics/cybersecurity/science-daily-2026-10-13.md</code>（同日 X-AgentRed）、<code>topics/biomedicine/index.md</code>（蛋白设计交叉）</p>',17)])])}const p=t(n,[["render",i]]);export{m as __pageData,p as default};
